from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_METHODS = ("card", "transfer")


def _err(message: str) -> dict:
    return {"ok": False, "error": message}


def _check_id(member: dict) -> str | None:
    """Validate the member id. Return an error message, or None if valid."""
    if not isinstance(member["id"], str) or not member["id"]:
        return "bad member id"
    return None


def _check_tier(member: dict) -> dict | None:
    """Validate the tier. Return an error result, or None if valid."""
    if member["tier"] != "basic" and member["tier"] != "gold":
        return _err("unknown tier")
    return None


def _check_amount(payment: dict) -> dict | None:
    """Validate the payment amount. Return an error result, or None if valid."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return _err("bad amount")
    return None


def _check_method(payment: dict) -> dict | None:
    """Validate the payment method. Return an error result, or None if valid."""
    if payment["method"] != "card" and payment["method"] != "transfer":
        return _err("unsupported method")
    return None


def _make_receipt(member: dict, payment: dict, action: str, fee: int) -> str:
    return f"{payment['method']}:{member['id']}:{action}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _err("malformed input")

    member = raw_member
    payment = raw_payment

    if "id" not in member or "status" not in member or "tier" not in member:
        return _err("missing member field")
    if "amount" not in payment or "method" not in payment:
        return _err("missing payment field")

    if (err := _check_id(member)) is not None:
        return _err(err)

    status = member["status"]
    if status == "banned":
        return _err("member banned")

    # The following validation order is intentionally preserved per status so
    # that the error reported on an invalid input is unchanged.
    if status == "active":
        if (err := _check_tier(member)) is not None:
            return err
        if (err := _check_amount(payment)) is not None:
            return err
        if (err := _check_method(payment)) is not None:
            return err
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return _err("insufficient payment")
        return {
            "ok": True,
            "status": "renewed",
            "fee": fee,
            "receipt": _make_receipt(member, payment, "renewed", fee),
        }

    if status == "lapsed":
        if (err := _check_tier(member)) is not None:
            return err
        if (
            "expired_days" not in member
            or not isinstance(member["expired_days"], int)
            or member["expired_days"] < 0
        ):
            return _err("bad expiry")
        if (err := _check_amount(payment)) is not None:
            return err
        if (err := _check_method(payment)) is not None:
            return err
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return _err("insufficient payment")
        return {
            "ok": True,
            "status": new_status,
            "fee": fee,
            "receipt": _make_receipt(member, payment, new_status, fee),
        }

    if status == "suspended":
        if (err := _check_tier(member)) is not None:
            return err
        if (
            "strikes" not in member
            or not isinstance(member["strikes"], int)
            or member["strikes"] < 0
        ):
            return _err("bad strikes")
        if member["strikes"] >= MAX_STRIKES:
            return _err("too many strikes")
        if (err := _check_amount(payment)) is not None:
            return err
        if (err := _check_method(payment)) is not None:
            return err
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        if payment["amount"] < fee:
            return _err("insufficient payment")
        return {
            "ok": True,
            "status": "reactivated",
            "fee": fee,
            "receipt": _make_receipt(member, payment, "reactivated", fee),
        }

    return _err("unknown status")
